def transform(grid):
    """Copy the marked shape onto every all-zero placement of its footprint."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return [row[:] for row in grid]
    color = min(counts, key=counts.get)
    marks = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
    shape = [(r-min(x for x, _ in marks), c-min(y for _, y in marks)) for r, c in marks]
    sh, sw = max(r for r, _ in shape)+1, max(c for _, c in shape)+1
    out = [row[:] for row in grid]
    for r0 in range(h-sh+1):
        for c0 in range(w-sw+1):
            cells = [(r0+dr, c0+dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
